// Generated by hand from `android/app/google-services.json` and
// `ios/Runner/GoogleService-Info.plist` (project `sothuchi-d055a`) — the
// same values a real `flutterfire configure` run would produce.
//
// Passing these explicitly to `Firebase.initializeApp(options: ...)`
// (see main.dart) makes Firebase init succeed regardless of whether the
// native config file is actually bundled by the platform build — Android
// reads `google-services.json` automatically via the Gradle plugin either
// way, but iOS only picks up `GoogleService-Info.plist` if it was added to
// the Xcode project's Runner target as a resource, a manual Xcode step that
// can't be done from this Windows environment (no Mac). Without this file,
// a not-yet-bundled plist made `Firebase.initializeApp()` throw before
// `runApp()` ever ran, producing a blank white screen on iOS with Android
// completely unaffected (it doesn't depend on this file at all).
import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart' show defaultTargetPlatform, kIsWeb, TargetPlatform;

class DefaultFirebaseOptions {
  DefaultFirebaseOptions._();

  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      throw UnsupportedError('DefaultFirebaseOptions have not been configured for web.');
    }
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      case TargetPlatform.iOS:
        return ios;
      default:
        throw UnsupportedError('DefaultFirebaseOptions are not supported for this platform.');
    }
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyAAwNxHKDAZzMSInH2jBog9k6briy4FSws',
    appId: '1:57154351827:android:a0e511b2a49760e7125a26',
    messagingSenderId: '57154351827',
    projectId: 'sothuchi-d055a',
    storageBucket: 'sothuchi-d055a.firebasestorage.app',
  );

  static const FirebaseOptions ios = FirebaseOptions(
    apiKey: 'AIzaSyDP8CVi_TJ11J-uvoVbOfQX6ONo4xJ-PXg',
    appId: '1:57154351827:ios:ab93f814a229965e125a26',
    messagingSenderId: '57154351827',
    projectId: 'sothuchi-d055a',
    storageBucket: 'sothuchi-d055a.firebasestorage.app',
